for (const language of Object.keys(TRANSLATIONS) as SupportedLanguage[]) {
  Object.assign(TRANSLATIONS[language], SUPPLEMENTAL_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], ADD_FIGURE_CHOICE_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], FIGURE_GALLERY_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], DELETE_CONFIRM_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], DETAIL_LABEL_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], FORM_EXAMPLE_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], LIVE_STATUS_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], PAGINATION_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], DEMO_AUTH_TRANSLATIONS[language]);
  Object.assign(TRANSLATIONS[language], AUTH_FLOW_TRANSLATIONS[language]);
  TRANSLATIONS[language]['auth.recovery_unavailable'] = AUTH_RECOVERY_STATUS[language];
  TRANSLATIONS[language]['auth.email_recovery_note'] = AUTH_EMAIL_NOTE[language];
  TRANSLATIONS[language]['auth.legal_expand'] = AUTH_LEGAL_COMPACT[language].title;
  TRANSLATIONS[language]['auth.legal_short'] = AUTH_LEGAL_COMPACT[language].summary;
  TRANSLATIONS[language]['consent.session_activation_failed'] = CONSENT_FLOW_ERRORS[language];
}

interface LanguageContextType {
  currentLanguage: SupportedLanguage;
  setLanguage: (lang: SupportedLanguage) => void;
  t: (key: string, defaultText?: string) => string;
  languages: LanguageOption[];
}

const LanguageContext = createContext<LanguageContextType>({
  currentLanguage: 'ca',
  setLanguage: () => {},
  t: (key, defaultText) => defaultText || key,
  languages: SUPPORTED_LANGUAGES
});

export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentLanguage, setCurrentLanguageState] = useState<SupportedLanguage>(() => {
    const saved = localStorage.getItem('cb_language') as SupportedLanguage | null;
    if (saved && TRANSLATIONS[saved]) {
      return saved;
    }
    // Català per defecte tal com ha demanat l'usuari
    return 'ca';
  });

  const setLanguage = (lang: SupportedLanguage) => {
    if (TRANSLATIONS[lang]) {
      setCurrentLanguageState(lang);
      localStorage.setItem('cb_language', lang);
      document.documentElement.lang = lang;
    }
  };

  useEffect(() => {
    document.documentElement.lang = currentLanguage;
  }, [currentLanguage]);

  const t = (key: string, defaultText?: string): string => {
    const langDict = TRANSLATIONS[currentLanguage];
    if (langDict && langDict[key]) {
      return langDict[key];
    }
    // Fallback to Catalan default, then English, then defaultText
    if (TRANSLATIONS.ca && TRANSLATIONS.ca[key]) {
      return TRANSLATIONS.ca[key];
    }
    if (TRANSLATIONS.en && TRANSLATIONS.en[key]) {
      return TRANSLATIONS.en[key];
    }
    return defaultText || key;
  };

  return (
    <LanguageContext.Provider value={{ currentLanguage, setLanguage, t, languages: SUPPORTED_LANGUAGES }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => useContext(LanguageContext);
